CREATE SEQUENCE "ORCT_DocNum_seq" START WITH 3001;
CREATE SEQUENCE "OVPM_DocNum_seq" START WITH 4001;

-- Incoming payments. DocTotal exists here but not in the API, see docs/sl-contract.md.
CREATE TABLE "ORCT" (
    "DocEntry" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DocNum"   INT            NOT NULL DEFAULT nextval('"ORCT_DocNum_seq"') UNIQUE,
    "DocType"  VARCHAR(1)     NOT NULL DEFAULT 'C' CHECK ("DocType" IN ('C', 'A', 'S')),
    "Canceled" VARCHAR(1)     NOT NULL DEFAULT 'N' CHECK ("Canceled" IN ('Y', 'N', 'C')),
    "DocDate"  DATE           NOT NULL,
    "CardCode" VARCHAR(15)    NOT NULL REFERENCES "OCRD" ("CardCode"),
    "CardName" VARCHAR(200),
    "CashAcct" VARCHAR(15)    NOT NULL REFERENCES "OACT" ("AcctCode"),
    "CashSum"  NUMERIC(19, 6) NOT NULL,
    "DocTotal" NUMERIC(19, 6) NOT NULL,
    "Comments" VARCHAR(254)
);

-- Which sale a payment settles. The names mislead:
-- DocNum points to ORCT.DocEntry (the payment), DocEntry points to OINV.DocEntry (the sale).
CREATE TABLE "RCT2" (
    "DocNum"     INT            NOT NULL REFERENCES "ORCT" ("DocEntry"),
    "InvoiceId"  INT            NOT NULL,
    "DocEntry"   INT            NOT NULL REFERENCES "OINV" ("DocEntry"),
    "SumApplied" NUMERIC(19, 6) NOT NULL,
    "InvType"    VARCHAR(20)    NOT NULL DEFAULT '13',
    "InstId"     INT            NOT NULL DEFAULT 1,
    PRIMARY KEY ("DocNum", "InvoiceId")
);

-- Outgoing payments, the same structure as ORCT.
CREATE TABLE "OVPM" (
    "DocEntry" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DocNum"   INT            NOT NULL DEFAULT nextval('"OVPM_DocNum_seq"') UNIQUE,
    "DocType"  VARCHAR(1)     NOT NULL DEFAULT 'S' CHECK ("DocType" IN ('C', 'A', 'S')),
    "Canceled" VARCHAR(1)     NOT NULL DEFAULT 'N' CHECK ("Canceled" IN ('Y', 'N', 'C')),
    "DocDate"  DATE           NOT NULL,
    "CardCode" VARCHAR(15)    NOT NULL REFERENCES "OCRD" ("CardCode"),
    "CardName" VARCHAR(200),
    "CashAcct" VARCHAR(15)    NOT NULL REFERENCES "OACT" ("AcctCode"),
    "CashSum"  NUMERIC(19, 6) NOT NULL,
    "DocTotal" NUMERIC(19, 6) NOT NULL,
    "Comments" VARCHAR(254)
);

-- Which purchase a payment settles, the same structure as RCT2.
CREATE TABLE "VPM2" (
    "DocNum"     INT            NOT NULL REFERENCES "OVPM" ("DocEntry"),
    "InvoiceId"  INT            NOT NULL,
    "DocEntry"   INT            NOT NULL REFERENCES "OPCH" ("DocEntry"),
    "SumApplied" NUMERIC(19, 6) NOT NULL,
    "InvType"    VARCHAR(20)    NOT NULL DEFAULT '18',
    "InstId"     INT            NOT NULL DEFAULT 1,
    PRIMARY KEY ("DocNum", "InvoiceId")
);
